"""Authored Mavis route. Pure manuscript data; no state mutation or combat results.

Aftermath is displayed only after the runtime validates the relevant receipt.
Variants are selected by explicit route facts, never by an AI inference.
"""

def b(speaker=None, text='', narration='', *, memory=False):
    beat = {'player': '', 'speeches': [[speaker, text]] if speaker else [],
            'narration': narration}
    if memory:
        beat['mode'] = 'memory'
    return beat


def m(speaker=None, text='', narration=''):
    return b(speaker, text, narration, memory=True)


