# Bind every scripted historical speaker to the independent period, including
# speakers unavailable for optional visits. The runtime keeps these beats in the
# historical session and appends after_encounter only after a successful result.
for _memory in MEMORIES.values():
    for _field in ('text', 'after_encounter'):
        for _beat in _memory.get(_field, []):
            _beat['era'] = _memory['era']
            _beat['memory_id'] = next(key for key, value in MEMORIES.items() if value is _memory)


def validate_inventory():
    """Small data integrity check; not a gameplay or continuity certification."""
    assert tuple(CHAPTERS) == tuple(f'MV-{n:02}' for n in range(1, 13))
    assert tuple(MEMORIES) == tuple(f'MV-F{n:02}' for n in range(1, 7))
    assert {v['memory'] for v in CHAPTERS.values() if 'memory' in v} == set(MEMORIES)
    for memory in MEMORIES.values():
        assert all(beat.get('mode') == 'memory' for key in ('text', 'after_encounter') for beat in memory.get(key, []))
    return True


# Presentation metadata is authored separately from gameplay authority.
