_visuals.apply(CHAPTERS, MEMORIES, DISCLOSURES, OUTCOME_VARIANTS)
for _who, _beats in SUPPORT_SCENES.items():
    _visuals.bind(_beats, 'MV-10:support:' + _who, _visuals.HQ)
for _priority, _beats in PRIORITY_SCENES.items():
    _visuals.bind(_beats, 'MV-10:priority:' + _priority, _visuals.HQ)
for _chapter, _beats in OBJECTIVE_SCENES.items():
    _visuals.bind(_beats, _chapter + ':objective', _visuals.EXCHANGE,
                  _visuals.CURRENT | {'mavis': 'mavis-syndicate'})
